func encResolveRequest(out []byte, v *ResolveRequest, depth int) []byte {
	if !(v.Scope).Known() {
		panic(&Refusal{Word: "bad_enum", Offset: 0})
	}
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "capability")
	out = append(out, ':', ' ')
	out = esc(out, v.Capability)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "contracts")
	out = append(out, ':', ' ')
	out = strs(out, v.Contracts, depth+1)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "guarantees")
	out = append(out, ':', ' ')
	out = strs(out, v.Guarantees, depth+1)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "scope")
	out = append(out, ':', ' ')
	out = esc(out, v.Scope.String())
	out = append(out, '\n')
	out = pad(out, depth)
	return append(out, '}')
}

